const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],KEY="aibeep-online-v1";
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const safeUrl=s=>{try{const u=new URL(s);return u.protocol==="https:"||u.protocol==="http:"}catch{return false}};
let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}if(!state||!Array.isArray(state.items))state={items:[],drafts:{}};if(!state.drafts||typeof state.drafts!=="object")state.drafts={};
function persist(){localStorage.setItem(KEY,JSON.stringify(state));render()}
let toastTimer;function toast(s){$("#toast").textContent=s;$("#toast").style.display="block";clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("#toast").style.display="none",2500)}
const names={featured:"精选",intel:"全部动态",hot:"热点榜",digest:"增长日报",themes:"主题",article:"文章阅读",home:"关于 AIBEEP",topics:"收藏",sources:"信源中心",editor:"内容工作台",settings:"设置与数据",changelog:"更新日志",feedback:"反馈"};
function go(v){$$(".view").forEach(e=>e.classList.toggle("active",e.id===v));$$(".nav").forEach(e=>e.classList.toggle("active",e.dataset.v===v));const crumb=$("#crumb");if(crumb)crumb.textContent=names[v]||"AIBEEP";render();window.scrollTo(0,0)}
$$("[data-v]").forEach(e=>e.addEventListener("click",()=>go(e.dataset.v)));
$$(".add").forEach(e=>e.onclick=()=>$("#overlay").classList.add("show"));$("#cancel").onclick=()=>$("#overlay").classList.remove("show");$("#overlay").onclick=e=>{if(e.target.id==="overlay")e.target.classList.remove("show")};
$("#form").onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),url=String(f.get("url")).trim();if(!safeUrl(url))return toast("原文链接格式错误");state.items.unshift({id:crypto.randomUUID(),title:String(f.get("title")).trim(),category:String(f.get("category")),source:String(f.get("source")).trim(),url,summary:String(f.get("summary")).trim(),addedAt:new Date().toISOString(),saved:false});persist();e.target.reset();$("#overlay").classList.remove("show");go("intel");toast("已保存情报")};
function row(x){return '<article class="feed"><div class="meta"><span class="tag">'+esc(x.category)+'</span><span>'+esc(x.source)+'</span><span>录入于 '+new Date(x.addedAt).toLocaleDateString("zh-CN")+'</span></div><h3>'+esc(x.title)+'</h3><p>'+esc(x.summary)+'</p><a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">原始来源 ↗</a><div class="feedbuttons"><button class="btn small" data-save="'+esc(x.id)+'">'+(x.saved?"★ 已收藏":"☆ 收藏选题")+'</button><button class="btn small" data-del="'+esc(x.id)+'">删除</button></div></article>'}
function feed(container,items){container.innerHTML=items.length?items.map(row).join(""):'<div class="empty"><b>暂时还没有情报</b><span>点击「添加情报」录入真实文章和来源。</span></div>'}
function render(){let q=$("#qIntel").value.trim().toLowerCase(),f=$("#fIntel").value;feed($("#recent"),state.items.slice(0,5));feed($("#allIntel"),state.items.filter(x=>(!f||x.category===f)&&(!q||[x.title,x.category,x.source,x.summary].join(" ").toLowerCase().includes(q))));$("#nIntel").textContent=state.items.length;const saved=state.items.filter(x=>x.saved);$("#nTopics").textContent=saved.length;$("#topicList").innerHTML=saved.length?saved.map(x=>'<div class="card topic"><span class="tag">'+esc(x.category)+'</span><h3>'+esc(x.title)+'</h3><p>'+esc(x.summary)+'</p><button class="btn small" data-write="'+esc(x.id)+'">去写内容 →</button> <button class="btn small" data-unsave="'+esc(x.id)+'">取消收藏</button></div>').join(""):'<div class="card empty"><b>还没有收藏内容</b><span>去「精选」或「全部动态」收藏值得研究的信息。</span></div>';let keep=$("#editTopic").value;$("#editTopic").innerHTML='<option value="">请选择收藏选题</option>'+saved.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.title)+'</option>').join("");$("#editTopic").value=keep;renderSources();if(typeof renderEditorial==="function")renderEditorial()}
function renderSources(){const q=$("#qSources").value.toLowerCase(),p=$("#fPriority").value,m=$("#fMarket").value,filtered=raw.filter(x=>(!q||x[0].toLowerCase().includes(q))&&(!p||p===x[3])&&(!m||m===x[1]));const count=$("#sourceResults");if(count)count.textContent=filtered.length;$("#sourceList").innerHTML=filtered.map(x=>'<tr><td><strong>'+esc(x[0])+'</strong></td><td>'+esc(x[2])+'</td><td><span class="tag '+(x[3]==="P0"?"":"gray")+'">'+x[3]+'</span></td><td>'+esc(x[4])+'</td><td><span class="tag orange">尚未验收</span></td><td><a href="'+esc(x[5])+'" target="_blank" rel="noopener noreferrer">查看 ↗</a></td></tr>').join("")||'<tr><td colspan="6">没有匹配信源</td></tr>'}
document.addEventListener("click",e=>{const s=e.target.closest("[data-save]"),d=e.target.closest("[data-del]"),u=e.target.closest("[data-unsave]"),w=e.target.closest("[data-write]");if(s){const x=state.items.find(x=>x.id===s.dataset.save);if(x){x.saved=!x.saved;persist();toast(x.saved?"已加入选题库":"已取消收藏")}}if(d&&confirm("确定删除这条情报吗？")){state.items=state.items.filter(x=>x.id!==d.dataset.del);persist()}if(u){const x=state.items.find(x=>x.id===u.dataset.unsave);if(x){x.saved=false;persist()}}if(w){go("editor");$("#editTopic").value=w.dataset.write;$("#draft").value=state.drafts[w.dataset.write]||""}});
["qIntel","fIntel","qSources","fPriority","fMarket"].forEach(id=>$("#"+id).addEventListener("input",render));$("#editTopic").onchange=()=>$("#draft").value=state.drafts[$("#editTopic").value]||"";
$("#outline").onclick=()=>{const x=state.items.find(x=>x.id===$("#editTopic").value);if(!x)return toast("请先选择一个收藏选题");const fmt=$("#editFormat").value;let body=fmt==="60秒口播"?"开头具体场景：\n\n发生的变化："+x.summary+"\n\n结合我自己的投放经验：\n\n还有什么需要验证：":fmt==="X 帖子"?"事实："+x.summary+"\n\n当时怎么想：\n\n顺手判断：":fmt==="小红书图文"?"封面标题：\n\n具体信息："+x.summary+"\n\n适用人群：\n\n可执行建议：":"背景：\n\n变化："+x.summary+"\n\n核心问题：\n\n我的判断与方法（填写实际经验）：";$("#draft").value="选题："+x.title+"\n形式："+fmt+"\n原文："+x.url+"\n\n"+body;toast("已生成可编辑内容框架")};
$("#saveDraft").onclick=()=>{const id=$("#editTopic").value;if(!id)return toast("请选择选题");state.drafts[id]=$("#draft").value;persist();toast("草稿已保存")};$("#copyDraft").onclick=async()=>{try{await navigator.clipboard.writeText($("#draft").value);toast("已复制文字")}catch{toast("复制失败，请手动复制")}};
$("#export").onclick=()=>{const blob=new Blob([JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="aibeep-backup-"+new Date().toISOString().slice(0,10)+".json";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$("#import").onclick=()=>$("#file").click();$("#file").onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const v=JSON.parse(await f.text());if(!Array.isArray(v.items)||v.items.length>10000||v.items.some(x=>!safeUrl(x.url)||typeof x.title!=="string"))throw Error();if(!confirm("导入将替换当前浏览器数据，确认吗？"))return;state={items:v.items.map(x=>({...x,id:String(x.id||crypto.randomUUID()),addedAt:x.addedAt||new Date().toISOString(),saved:!!x.saved})),drafts:v.drafts&&typeof v.drafts==="object"?v.drafts:{}};persist();toast("数据导入成功")}catch{toast("导入失败，备份格式不正确")}finally{e.target.value=""}};
render();
